  function unifyAndDeduplicateImprovementIssues(
    issues: ImprovementIssue[]
  ): {
    unified_issues: (ImprovementIssue & { group_cohesion_score: number })[];
    total_input_count: number;
    total_deduplicated_count: number;
    duplicates_removed_count: number;
    unified_groups_count: number;
    deduplication_rate: number;
    unification_completed: boolean;
  } {
    const total_input_count = issues.length;
  
    // Step 1: Deduplicate by issue_id (keep first occurrence)
    const seen_ids = new Set<string>();
    const deduplicated: ImprovementIssue[] = [];
  
    for (const issue of issues) {
      if (!seen_ids.has(issue.issue_id)) {
        seen_ids.add(issue.issue_id);
        deduplicated.push(issue);
      }
    }
  
    const total_deduplicated_count = deduplicated.length;
    const duplicates_removed_count = total_input_count - total_deduplicated_count;
  
    // Step 2: Build relationship graph and identify unified groups
    const issue_map = new Map<string, ImprovementIssue>();
    deduplicated.forEach((issue) => {
      issue_map.set(issue.issue_id, issue);
    });
  
    const visited = new Set<string>();
    const groups: Set<string>[] = [];
  
    const dfs = (issue_id: string, group: Set<string>) => {
      if (visited.has(issue_id)) return;
      visited.add(issue_id);
      group.add(issue_id);
  
      const issue = issue_map.get(issue_id);
      if (issue && issue.related_issues) {
        for (const related_id of issue.related_issues) {
          if (issue_map.has(related_id)) {
            dfs(related_id, group);
          }
        }
      }
    };
  
    for (const issue of deduplicated) {
      if (!visited.has(issue.issue_id)) {
        const group = new Set<string>();
        dfs(issue.issue_id, group);
        groups.push(group);
      }
    }
  
    const unified_groups_count = groups.length;
  
    // Step 3: Build unified issues with group cohesion score
    const unified_issues: (ImprovementIssue & { group_cohesion_score: number })[] =
      [];
  
    for (const issue of deduplicated) {
      // Find the group this issue belongs to
      const group = groups.find((g) => g.has(issue.issue_id));
      const group_size = group ? group.size : 1;
  
      // Calculate group cohesion score based on group size and priority
      // Larger groups with higher priority issues have higher cohesion
      const base_cohesion = (group_size / Math.max(group_size, 5)) * 50;
      const priority_factor = (issue.priority_score / 10) * 50;
      const group_cohesion_score = Math.min(100, base_cohesion + priority_factor);
  
      unified_issues.push({
        ...issue,
        group_cohesion_score: Math.round(group_cohesion_score * 100) / 100,
      });
    }
  
    // Step 4: Sort by issue_id for consistent ordering
    unified_issues.sort((a, b) => a.issue_id.localeCompare(b.issue_id));
  
    // Step 5: Calculate deduplication rate
    const deduplication_rate =
      total_input_count > 0
        ? (duplicates_removed_count / total_input_count) * 100
        : 0;
  
    return {
      unified_issues,
      total_input_count,
      total_deduplicated_count,
      duplicates_removed_count,
      unified_groups_count,
      deduplication_rate: Math.round(deduplication_rate * 100) / 100,
      unification_completed: true,
    };
  }
