const __aivicBundle_7_mergeImprovementIssues = (() => {
  function mergeImprovementIssues(
    issues: Array<{
      issueId: string;
      issueTitle: string;
      segmentIds: string[];
      restrictionIds: string[];
      impactScore: number;
    }>
  ): {
    mergedIssues: Array<{
      issueId: string;
      issueTitle: string;
      affectedSegmentIds: string[];
      affectedRestrictionIds: string[];
      impactRangeSize: number;
      maxImpactScore: number;
    }>;
    deduplicationCount: number;
    totalProcessed: number;
  } {
    const totalProcessed = issues.length;
    const issueMap = new Map<
      string,
      {
        issueId: string;
        issueTitle: string;
        segmentIds: Set<string>;
        restrictionIds: Set<string>;
        maxImpactScore: number;
      }
    >();
  
    for (const issue of issues) {
      const key = issue.issueId;
  
      if (issueMap.has(key)) {
        const existing = issueMap.get(key)!;
        issue.segmentIds.forEach((seg) => existing.segmentIds.add(seg));
        issue.restrictionIds.forEach((rest) => existing.restrictionIds.add(rest));
        existing.maxImpactScore = Math.max(existing.maxImpactScore, issue.impactScore);
      } else {
        issueMap.set(key, {
          issueId: issue.issueId,
          issueTitle: issue.issueTitle,
          segmentIds: new Set(issue.segmentIds),
          restrictionIds: new Set(issue.restrictionIds),
          maxImpactScore: issue.impactScore,
        });
      }
    }
  
    const mergedIssues = Array.from(issueMap.values()).map((item) => {
      const affectedSegmentIds = Array.from(item.segmentIds);
      const affectedRestrictionIds = Array.from(item.restrictionIds);
      const impactRangeSize = affectedSegmentIds.length * affectedRestrictionIds.length;
  
      return {
        issueId: item.issueId,
        issueTitle: item.issueTitle,
        affectedSegmentIds,
        affectedRestrictionIds,
        impactRangeSize,
        maxImpactScore: item.maxImpactScore,
      };
    });
  
    const deduplicationCount = totalProcessed - mergedIssues.length;
  
    return {
      mergedIssues,
      deduplicationCount,
      totalProcessed,
    };
  }
  return { mergeImprovementIssues };
})();
