/* AIVIC_FUNCTION_BUNDLE_START owner=verifyNutritionBaselineImprovement exports=verifyNutritionBaselineImprovement */
const __aivicBundle_16_verifyNutritionBaselineImprovement = (() => {
  function verifyNutritionBaselineImprovement(input: any): any {
    const {
      baseline_before_deployment,
      baseline_after_deployment,
      actual_intake_records,
      improvement_threshold,
    } = input;
  
    // Validate input
    if (!actual_intake_records || actual_intake_records.length === 0) {
      throw new Error("食事記録データが必要です");
    }
  
    if (
      !baseline_before_deployment ||
      !baseline_after_deployment ||
      improvement_threshold === undefined
    ) {
      throw new Error("必須パラメータが不足しています");
    }
  
    // Calculate average deviations before deployment
    const nutrientsBefore = calculateAverageDeviations(
      actual_intake_records,
      baseline_before_deployment
    );
    const average_deviation_before = nutrientsBefore.average;
  
    // Calculate average deviations after deployment
    const nutrientsAfter = calculateAverageDeviations(
      actual_intake_records,
      baseline_after_deployment
    );
    const average_deviation_after = nutrientsAfter.average;
  
    // Calculate improvement rate
    const improvement_rate =
      average_deviation_before !== 0
        ? (average_deviation_before - average_deviation_after) /
          Math.abs(average_deviation_before)
        : 0;
  
    // Determine if improvement is detected
    const improvement_detected = improvement_rate >= improvement_threshold;
  
    // Determine quality verdict
    let qualityVerdict: "pass" | "conditional_pass" | "fail" = "fail";
    if (improvement_detected && improvement_rate >= improvement_threshold) {
      qualityVerdict = "pass";
    } else if (improvement_rate >= 0 && improvement_rate < improvement_threshold) {
      qualityVerdict = "conditional_pass";
    }
  
    // Generate error message if needed
    let error_message: string | null = null;
    let alert_issued = false;
  
    if (!improvement_detected) {
      error_message = `改善効果が検出されません。改善率: ${(improvement_rate * 100).toFixed(2)}%`;
      alert_issued = true;
    }
  
    if (improvement_rate < 0) {
      error_message = `改善効果が検出されません。改善率: ${(improvement_rate * 100).toFixed(2)}%`;
      alert_issued = true;
    }
  
    // Create log entry
    const log_entry = {
      severity: alert_issued ? "error" : "info",
      timestamp: new Date().toISOString(),
      message: error_message || "栄養基準改善の検証が完了しました",
    };
  
    // Calculate nutrient-wise deviations
    const nutrient_wise_deviations: Record<string, number> = {};
    const nutrients = ["protein", "carbs", "fat", "fiber"];
  
    for (const nutrient of nutrients) {
      const deviationsBefore = actual_intake_records.map((record: any) => {
        const min = (baseline_before_deployment as any)[`${nutrient}_min`];
        const max = (baseline_before_deployment as any)[`${nutrient}_max`];
        const actual = record[nutrient];
        const midpoint = (min + max) / 2;
        return actual - midpoint;
      });
  
      const deviationsAfter = actual_intake_records.map((record: any) => {
        const min = (baseline_after_deployment as any)[`${nutrient}_min`];
        const max = (baseline_after_deployment as any)[`${nutrient}_max`];
        const actual = record[nutrient];
        const midpoint = (min + max) / 2;
        return actual - midpoint;
      });
  
      const avgBefore =
        deviationsBefore.reduce((a: number, b: number) => a + b, 0) /
        deviationsBefore.length;
      const avgAfter =
        deviationsAfter.reduce((a: number, b: number) => a + b, 0) /
        deviationsAfter.length;
  
      nutrient_wise_deviations[nutrient] = avgAfter - avgBefore;
    }
  
    return {
      improvement_detected,
      average_deviation_before,
      average_deviation_after,
      improvement_rate,
      error_message,
      alert_issued,
      log_entry,
      nutrient_wise_deviations,
    };
  }
  
  function calculateAverageDeviations(
    records: any[],
    baseline: any
  ): { average: number; deviations: number[] } {
    const nutrients = ["protein", "carbs", "fat", "fiber"];
    const allDeviations: number[] = [];
  
    for (const nutrient of nutrients) {
      const min = baseline[`${nutrient}_min`];
      const max = baseline[`${nutrient}_max`];
      const midpoint = (min + max) / 2;
  
      const deviations = records.map((record: any) => {
        const actual = record[nutrient];
        return actual - midpoint;
      });
  
      allDeviations.push(
        ...deviations.map((d: number) => Math.abs(d) / midpoint)
      );
    }
  
    const average =
      allDeviations.length > 0
        ? allDeviations.reduce((a: number, b: number) => a + b, 0) /
          allDeviations.length
        : 0;
  
    return { average, deviations: allDeviations };
  }
  return { verifyNutritionBaselineImprovement };
})();
