/* AIVIC_FUNCTION_BUNDLE_START owner=validateNutritionImprovementEffect exports=validateNutritionImprovementEffect */
const __aivicBundle_17_validateNutritionImprovementEffect = (() => {
  interface ValidateNutritionImprovementEffectInput {
    targetValue: number;
    actualValue: number;
    thresholdPercentage: number;
  }
  
  interface ValidateNutritionImprovementEffectOutput {
    isImproved: boolean;
    variancePercentage: number;
  }
  
   function validateNutritionImprovementEffect(
    input: ValidateNutritionImprovementEffectInput
  ): ValidateNutritionImprovementEffectOutput {
    const { targetValue, actualValue, thresholdPercentage } = input;
  
    const variancePercentage =
      ((actualValue - targetValue) / targetValue) * 100;
  
    const lowerBound = targetValue * (1 - thresholdPercentage / 100);
    const upperBound = targetValue * (1 + thresholdPercentage / 100);
  
    const isImproved = actualValue >= lowerBound && actualValue <= upperBound;
  
    return {
      isImproved,
      variancePercentage,
    };
  }
  return { validateNutritionImprovementEffect };
})();
