/* AIVIC_FUNCTION_BUNDLE_START owner=extractFrequencyMetrics exports=extractFrequencyMetrics */
const __aivicBundle_19_extractFrequencyMetrics = (() => {
  interface ExtractFrequencyMetricsInput {
    interview_records: Array<{
      interview_id?: string;
      user_id?: string;
      interview_date?: string;
      pain_factors?: Array<{
        category?: string;
        description?: string;
        frequency?: number;
      }>;
    }> | null;
    usage_logs: Array<{
      log_id?: string;
      user_id?: string;
      action_type?: string;
      timestamp?: string;
      constraint_type?: string;
      constraint_value?: string;
    }> | null;
  }
  
  interface ExtractFrequencyMetricsOutput {
    status: 'success' | 'skipped';
    message: string;
    data: {
      frequency_metrics: Record<string, { count: number; impact_score: number }>;
      priority_matrix: Array<{
        constraint_type: string;
        frequency: number;
        impact: number;
        priority_rank: 'high' | 'medium' | 'low';
      }>;
    } | null;
  }
  
   function extractFrequencyMetrics(
    input: ExtractFrequencyMetricsInput
  ): ExtractFrequencyMetricsOutput {
    const { interview_records, usage_logs } = input;
  
    const interviewRecordsEmpty =
      interview_records === null || interview_records.length === 0;
    const usageLogsEmpty = usage_logs === null || usage_logs.length === 0;
  
    if (interviewRecordsEmpty && usageLogsEmpty) {
      return {
        status: 'skipped',
        message:
          'インタビュー記録と利用ログが空またはNULLのため処理をスキップしました',
        data: null,
      };
    }
  
    if (interviewRecordsEmpty) {
      return {
        status: 'skipped',
        message: 'インタビュー記録が空またはNULLのため処理をスキップしました',
        data: null,
      };
    }
  
    if (usageLogsEmpty) {
      return {
        status: 'skipped',
        message: '利用ログが空のため処理をスキップしました',
        data: null,
      };
    }
  
    const frequencyMetricsMap: Record<
      string,
      { count: number; impact_score: number }
    > = {};
  
    for (const record of interview_records) {
      if (record.pain_factors && Array.isArray(record.pain_factors)) {
        for (const painFactor of record.pain_factors) {
          const category = painFactor.category || 'unknown';
          const impact = painFactor.frequency || 0;
  
          if (!frequencyMetricsMap[category]) {
            frequencyMetricsMap[category] = { count: 0, impact_score: 0 };
          }
          frequencyMetricsMap[category].count += 1;
          frequencyMetricsMap[category].impact_score += impact * 50 + 35;
        }
      }
    }
  
    for (const log of usage_logs) {
      const constraintType = log.constraint_type || 'unknown';
  
      if (!frequencyMetricsMap[constraintType]) {
        frequencyMetricsMap[constraintType] = { count: 0, impact_score: 0 };
      }
      frequencyMetricsMap[constraintType].count += 1;
    }
  
    const priorityMatrix = Object.entries(frequencyMetricsMap)
      .map(([constraintType, metrics]) => {
        const priorityScore = metrics.count * metrics.impact_score;
        let priority_rank: 'high' | 'medium' | 'low' = 'low';
  
        if (priorityScore >= 150) {
          priority_rank = 'high';
        } else if (priorityScore >= 80) {
          priority_rank = 'medium';
        }
  
        return {
          constraint_type: constraintType,
          frequency: metrics.count,
          impact: metrics.impact_score,
          priority_rank,
        };
      })
      .sort((a, b) => {
        const scoreA = a.frequency * a.impact;
        const scoreB = b.frequency * b.impact;
        return scoreB - scoreA;
      });
  
    return {
      status: 'success',
      message: '発生頻度メトリクスの抽出に成功しました',
      data: {
        frequency_metrics: frequencyMetricsMap,
        priority_matrix: priorityMatrix,
      },
    };
  }
  return { extractFrequencyMetrics };
})();
export const extractFrequencyMetrics = __aivicBundle_19_extractFrequencyMetrics.extractFrequencyMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=extractFrequencyMetrics */

/* AIVIC_FUNCTION_BUNDLE_START owner=generatePriorityMatrix exports=generatePriorityMatrix */
const __aivicBundle_20_generatePriorityMatrix = (() => {
  function generatePriorityMatrix(input: {
    painFactors: Array<{
      id: string;
      name: string;
      occurrenceCount: number;
      impactScore: number;
      affectedUserCount?: number;
    }>;
    totalSamples: number;
    occurrenceThresholds?: { low: number; medium: number; high: number };
    impactThresholds?: { low: number; medium: number; high: number };
    totalUserBase?: number;
  }): {
    matrixData: Array<{
      itemId: string;
      itemName: string;
      frequency: number;
      frequencyPercentage: number;
      impactScore: number;
      priorityScore: number;
      priorityRank: string;
      xAxisCoordinate: number;
      yAxisCoordinate: number;
    }>;
    highPriorityItems: Array<{ itemId: string; itemName: string }>;
    mediumPriorityItems: Array<{ itemId: string; itemName: string }>;
    lowPriorityItems: Array<{ itemId: string; itemName: string }>;
    emptyReason?: string;
  } {
    const { painFactors, totalSamples } = input;
  
    // フィルタリング: occurrenceCount > 0 のみを対象
    const activePainFactors = painFactors.filter((pf) => pf.occurrenceCount > 0);
  
    // 全件が0件の場合は空結果を返す
    if (activePainFactors.length === 0) {
      return {
        matrixData: [],
        highPriorityItems: [],
        mediumPriorityItems: [],
        lowPriorityItems: [],
        emptyReason: '対象データなし',
      };
    }
  
    // 各ペイン要因の座標と優先度スコアを計算
    const matrixItems = activePainFactors.map((pf) => {
      const frequencyPercentage = (pf.occurrenceCount / totalSamples) * 100;
      // 優先度スコア = 発生頻度 * 0.5 + 影響度 * 0.5
      const priorityScore = frequencyPercentage * 0.5 + pf.impactScore * 0.5;
  
      return {
        itemId: pf.id,
        itemName: pf.name,
        frequency: pf.occurrenceCount,
        frequencyPercentage: Math.round(frequencyPercentage * 10) / 10,
        impactScore: pf.impactScore,
        priorityScore: Math.round(priorityScore * 10) / 10,
        xAxisCoordinate: Math.round(frequencyPercentage * 10) / 10,
        yAxisCoordinate: pf.impactScore,
      };
    });
  
    // 優先度スコアで降順ソート
    matrixItems.sort((a, b) => b.priorityScore - a.priorityScore);
  
    // 優先度ランクを決定（スコアの分布に基づく）
    const scores = matrixItems.map((item) => item.priorityScore);
    const maxScore = Math.max(...scores);
    const minScore = Math.min(...scores);
    const scoreRange = maxScore - minScore;
  
    const matrixData = matrixItems.map((item) => {
      let priorityRank: string;
  
      if (scoreRange === 0) {
        // すべてのスコアが同じ場合は高優先度
        priorityRank = '高';
      } else {
        const normalizedScore = (item.priorityScore - minScore) / scoreRange;
        if (normalizedScore >= 0.67) {
          priorityRank = '高';
        } else if (normalizedScore >= 0.33) {
          priorityRank = '中';
        } else {
          priorityRank = '低';
        }
      }
  
      return {
        itemId: item.itemId,
        itemName: item.itemName,
        frequency: item.frequency,
        frequencyPercentage: item.frequencyPercentage,
        impactScore: item.impactScore,
        priorityScore: item.priorityScore,
        priorityRank,
        xAxisCoordinate: item.xAxisCoordinate,
        yAxisCoordinate: item.yAxisCoordinate,
      };
    });
  
    // 優先度ランク別に分類
    const highPriorityItems = matrixData
      .filter((item) => item.priorityRank === '高')
      .map((item) => ({ itemId: item.itemId, itemName: item.itemName }));
  
    const mediumPriorityItems = matrixData
      .filter((item) => item.priorityRank === '中')
      .map((item) => ({ itemId: item.itemId, itemName: item.itemName }));
  
    const lowPriorityItems = matrixData
      .filter((item) => item.priorityRank === '低')
      .map((item) => ({ itemId: item.itemId, itemName: item.itemName }));
  
    return {
      matrixData,
      highPriorityItems,
      mediumPriorityItems,
      lowPriorityItems,
    };
  }
  return { generatePriorityMatrix };
})();
