/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMenuGenerationFailurePatterns exports=analyzeMenuGenerationFailurePatterns */
const __aivicBundle_21_analyzeMenuGenerationFailurePatterns = (() => {
  function analyzeMenuGenerationFailurePatterns(
    input: any
  ): {
    total_patterns: number;
    analyzed_timestamp: string;
    categories: Array<{
      category_name: string;
      failure_count: number;
      percentage: number;
      average_impact_score: number;
      priority_score: number;
      affected_patterns: string[];
    }>;
  } {
    const patterns = Array.isArray(input) ? input : input.rejectionReasons || [];
  
    if (patterns.length === 0) {
      return {
        total_patterns: 0,
        analyzed_timestamp: new Date().toISOString(),
        categories: [],
      };
    }
  
    const categoryDefinitions: Record<
      string,
      { keywords: string[]; weight: number }
    > = {
      nutrition_imbalance: {
        keywords: [
          "栄養",
          "バランス",
          "タンパク質",
          "野菜",
          "栄養が不十分",
        ],
        weight: 8,
      },
      family_preference_mismatch: {
        keywords: ["好み", "嫌い", "好きな", "好きじゃない", "和食"],
        weight: 7,
      },
      cooking_time_exceeded: {
        keywords: ["調理時間", "時間", "分", "超える", "以内"],
        weight: 9,
      },
      allergen_restriction_missed: {
        keywords: [
          "アレルギー",
          "制限",
          "食べない",
          "使わない",
          "含まれている",
        ],
        weight: 10,
      },
      other: { keywords: [], weight: 0 },
    };
  
    const categoryMatches: Record<
      string,
      { patterns: string[]; impacts: number[] }
    > = {};
  
    Object.keys(categoryDefinitions).forEach((cat) => {
      categoryMatches[cat] = { patterns: [], impacts: [] };
    });
  
    patterns.forEach((pattern: any) => {
      const reasonText = (
        pattern.rejection_reason ||
        pattern.reasonText ||
        ""
      ).toLowerCase();
      const failureId = pattern.failure_id || pattern.id || "";
      const impactScore = pattern.impact_score || 0;
  
      let matched = false;
  
      for (const [categoryName, categoryDef] of Object.entries(
        categoryDefinitions
      )) {
        if (categoryName === "other") continue;
  
        const keywords = categoryDef.keywords;
        if (keywords.some((kw) => reasonText.includes(kw.toLowerCase()))) {
          categoryMatches[categoryName].patterns.push(failureId);
          categoryMatches[categoryName].impacts.push(impactScore);
          matched = true;
        }
      }
  
      if (!matched) {
        categoryMatches["other"].patterns.push(failureId);
        categoryMatches["other"].impacts.push(impactScore);
      }
    });
  
    const categories = Object.entries(categoryMatches)
      .map(([categoryName, data]) => {
        const failureCount = data.patterns.length;
        const percentage = (failureCount / patterns.length) * 100;
        const averageImpactScore =
          data.impacts.length > 0
            ? data.impacts.reduce((a, b) => a + b, 0) / data.impacts.length
            : 0;
  
        const frequencyWeight = (failureCount / patterns.length) * 40;
        const impactWeight = (averageImpactScore / 10) * 60;
        const priorityScore = frequencyWeight + impactWeight;
  
        return {
          category_name: categoryName,
          failure_count: failureCount,
          percentage: Math.round(percentage * 100) / 100,
          average_impact_score:
            Math.round(averageImpactScore * 100) / 100,
          priority_score: Math.round(priorityScore * 100) / 100,
          affected_patterns: data.patterns,
        };
      })
      .filter((cat) => cat.failure_count > 0)
      .sort((a, b) => b.priority_score - a.priority_score);
  
    return {
      total_patterns: patterns.length,
      analyzed_timestamp: new Date().toISOString(),
      categories,
    };
  }
  return { analyzeMenuGenerationFailurePatterns };
})();
