const __aivicBundle_22_analyzeFailurePatterns = (() => {
  function analyzeFailurePatterns(
    input?: unknown
  ): {
    classifications?: Array<{
      categoryId: string;
      categoryName: string;
      occurrenceCount: number;
      averageImpactScore: number;
      priorityRank: number;
    }>;
    impactAnalysis?: Array<{
      categoryId: string;
      hypothesis: string;
      recommendedAction: string;
      expectedEffectOnMetrics: {
        successRateImprovement: number;
        satisfactionScoreImprovement: number;
      };
    }>;
    summary?: Record<string, unknown>;
    combination_patterns?: Array<{
      reason_categories: string[];
      occurrence_count: number;
      confidence_score: number;
      related_record_ids: number[];
    }>;
    total_records_analyzed?: number;
    total_patterns_identified?: number;
    analysis_timestamp?: string;
    failedPatterns?: Array<{
      pattern: string;
      count: number;
      percentage: number;
    }>;
    totalCount?: number;
    analysisTimestamp?: string;
  } {
    const analysisTimestamp = new Date().toISOString();
  
    // Handle null/undefined/empty object inputs
    if (input === null || input === undefined) {
      return {
        failedPatterns: [],
        totalCount: 0,
        analysisTimestamp,
      };
    }
  
    // Handle empty array input
    if (Array.isArray(input) && input.length === 0) {
      return {
        classifications: [],
        impactAnalysis: [],
        summary: {},
      };
    }
  
    // Handle empty object input
    if (
      typeof input === "object" &&
      !Array.isArray(input) &&
      Object.keys(input).length === 0
    ) {
      return {
        failedPatterns: [],
        totalCount: 0,
        analysisTimestamp,
      };
    }
  
    // Handle structured input with failure_records and thresholds
    if (
      typeof input === "object" &&
      !Array.isArray(input) &&
      "failure_records" in input
    ) {
      const typedInput = input as {
        failure_records?: Array<{
          record_id: number;
          reason_category: string;
          reason_text: string;
          timestamp: string;
        }>;
        frequency_threshold?: number;
        confidence_threshold?: number;
      };
  
      const failureRecords = typedInput.failure_records || [];
      const frequencyThreshold = typedInput.frequency_threshold || 1;
      const confidenceThreshold = typedInput.confidence_threshold || 0;
  
      const totalRecordsAnalyzed = failureRecords.length;
  
      // Group by reason_category
      const categoryMap: Record<
        string,
        { count: number; recordIds: number[] }
      > = {};
      failureRecords.forEach((record) => {
        if (!categoryMap[record.reason_category]) {
          categoryMap[record.reason_category] = { count: 0, recordIds: [] };
        }
        categoryMap[record.reason_category].count += 1;
        categoryMap[record.reason_category].recordIds.push(record.record_id);
      });
  
      // Identify combination patterns (pairs of categories)
      const combinationPatterns: Array<{
        reason_categories: string[];
        occurrence_count: number;
        confidence_score: number;
        related_record_ids: number[];
      }> = [];
  
      const categories = Object.keys(categoryMap);
      for (let i = 0; i < categories.length; i++) {
        for (let j = i + 1; j < categories.length; j++) {
          const cat1 = categories[i];
          const cat2 = categories[j];
  
          // Find records that have both categories (simplified: count co-occurrences)
          const cat1Records = new Set(categoryMap[cat1].recordIds);
          const cat2Records = new Set(categoryMap[cat2].recordIds);
          const intersection = Array.from(cat1Records).filter((id) =>
            cat2Records.has(id)
          );
  
          if (intersection.length >= frequencyThreshold) {
            const confidenceScore = Math.min(
              100,
              (intersection.length / totalRecordsAnalyzed) * 100
            );
            if (confidenceScore >= confidenceThreshold) {
              combinationPatterns.push({
                reason_categories: [cat1, cat2],
                occurrence_count: intersection.length,
                confidence_score: confidenceScore,
                related_record_ids: intersection,
              });
            }
          }
        }
      }
  
      return {
        combination_patterns: combinationPatterns,
        total_records_analyzed: totalRecordsAnalyzed,
        total_patterns_identified: combinationPatterns.length,
        analysis_timestamp: analysisTimestamp,
      };
    }
  
    // Handle dictionary-style input (e.g., { '栄養バランス不適切': 15, ... })
    if (typeof input === "object" && !Array.isArray(input)) {
      const typedInput = input as Record<string, number>;
      const entries = Object.entries(typedInput);
  
      if (entries.length === 0) {
        return {
          failedPatterns: [],
          totalCount: 0,
          analysisTimestamp,
        };
      }
  
      const totalCount = entries.reduce((sum, [, count]) => sum + count, 0);
  
      const failedPatterns = entries.map(([pattern, count]) => ({
        pattern,
        count,
        percentage: (count / totalCount) * 100,
      }));
  
      return {
        failedPatterns,
        totalCount,
        analysisTimestamp,
      };
    }
  
    // Default fallback
    return {
      failedPatterns: [],
      totalCount: 0,
      analysisTimestamp,
    };
  }
  return { analyzeFailurePatterns };
})();
