/* AIVIC_FUNCTION_BUNDLE_START owner=classifyFailurePatterns exports=classifyFailurePatterns */
const __aivicBundle_23_classifyFailurePatterns = (() => {
  function classifyFailurePatterns(
    failurePatternData: Array<{
      pattern_id: string;
      failure_reason: string;
      category: string | null | undefined;
      occurrence_count: number;
      impact_score: number;
      rejection_frequency: number;
    }>
  ): {
    classified_patterns: Array<{
      pattern_id: string;
      failure_reason: string;
      normalized_category: string;
      original_category: string | null | undefined;
      occurrence_count: number;
      impact_score: number;
      rejection_frequency: number;
      error_handling_applied: boolean;
    }>;
    impact_analysis: {
      total_patterns_analyzed: number;
      patterns_with_undefined_category: number;
      defined_category_count: number;
      undefined_category_total_impact: number;
      undefined_category_occurrence_total: number;
      priority_matrix: Array<{
        category: string;
        total_occurrence: number;
        total_impact: number;
        frequency_rank: number;
        impact_rank: number;
        priority_score: number;
      }>;
    };
    classification_summary: {
      total_categories: number;
      categories_with_errors: string[];
    };
    exception_thrown: boolean;
    processing_completed: boolean;
  } {
    try {
      const classified_patterns = failurePatternData.map((pattern) => {
        const isUndefinedCategory =
          pattern.category === null || pattern.category === undefined;
        const normalized_category = isUndefinedCategory
          ? '予期しないカテゴリ'
          : pattern.category;
  
        return {
          pattern_id: pattern.pattern_id,
          failure_reason: pattern.failure_reason,
          normalized_category,
          original_category: pattern.category,
          occurrence_count: pattern.occurrence_count,
          impact_score: pattern.impact_score,
          rejection_frequency: pattern.rejection_frequency,
          error_handling_applied: isUndefinedCategory,
        };
      });
  
      const patterns_with_undefined_category = classified_patterns.filter(
        (p) => p.error_handling_applied
      ).length;
      const defined_category_count =
        classified_patterns.length - patterns_with_undefined_category;
  
      const undefined_category_total_impact = classified_patterns
        .filter((p) => p.error_handling_applied)
        .reduce((sum, p) => sum + p.impact_score, 0);
  
      const undefined_category_occurrence_total = classified_patterns
        .filter((p) => p.error_handling_applied)
        .reduce((sum, p) => sum + p.occurrence_count, 0);
  
      const categoryStats: Record<
        string,
        { total_occurrence: number; total_impact: number }
      > = {};
  
      classified_patterns.forEach((pattern) => {
        if (!categoryStats[pattern.normalized_category]) {
          categoryStats[pattern.normalized_category] = {
            total_occurrence: 0,
            total_impact: 0,
          };
        }
        categoryStats[pattern.normalized_category].total_occurrence +=
          pattern.occurrence_count;
        categoryStats[pattern.normalized_category].total_impact +=
          pattern.impact_score;
      });
  
      const categoryEntries = Object.entries(categoryStats);
  
      const sortedByOccurrence = [...categoryEntries].sort(
        (a, b) => b[1].total_occurrence - a[1].total_occurrence
      );
      const sortedByImpact = [...categoryEntries].sort(
        (a, b) => b[1].total_impact - a[1].total_impact
      );
  
      const frequency_rank_map: Record<string, number> = {};
      const impact_rank_map: Record<string, number> = {};
  
      sortedByOccurrence.forEach((entry, index) => {
        frequency_rank_map[entry[0]] = index + 1;
      });
  
      sortedByImpact.forEach((entry, index) => {
        impact_rank_map[entry[0]] = index + 1;
      });
  
      const priority_matrix = categoryEntries.map(([category, stats]) => {
        const frequency_rank = frequency_rank_map[category];
        const impact_rank = impact_rank_map[category];
        const priority_score =
          (1 / frequency_rank) * 0.5 + (1 / impact_rank) * 0.5;
  
        return {
          category,
          total_occurrence: stats.total_occurrence,
          total_impact: stats.total_impact,
          frequency_rank,
          impact_rank,
          priority_score,
        };
      });
  
      const unique_categories = new Set(
        classified_patterns.map((p) => p.normalized_category)
      );
      const categories_with_errors = classified_patterns
        .filter((p) => p.error_handling_applied)
        .map((p) => p.normalized_category);
      const unique_categories_with_errors = Array.from(
        new Set(categories_with_errors)
      );
  
      return {
        classified_patterns,
        impact_analysis: {
          total_patterns_analyzed: classified_patterns.length,
          patterns_with_undefined_category,
          defined_category_count,
          undefined_category_total_impact,
          undefined_category_occurrence_total,
          priority_matrix,
        },
        classification_summary: {
          total_categories: unique_categories.size,
          categories_with_errors: unique_categories_with_errors,
        },
        exception_thrown: false,
        processing_completed: true,
      };
    } catch {
      return {
        classified_patterns: [],
        impact_analysis: {
          total_patterns_analyzed: 0,
          patterns_with_undefined_category: 0,
          defined_category_count: 0,
          undefined_category_total_impact: 0,
          undefined_category_occurrence_total: 0,
          priority_matrix: [],
        },
        classification_summary: {
          total_categories: 0,
          categories_with_errors: [],
        },
        exception_thrown: true,
        processing_completed: false,
      };
    }
  }
  return { classifyFailurePatterns };
})();
export const classifyFailurePatterns = __aivicBundle_23_classifyFailurePatterns.classifyFailurePatterns;
/* AIVIC_FUNCTION_BUNDLE_END owner=classifyFailurePatterns */

