/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmVersions exports=compareAlgorithmVersions */
const __aivicBundle_27_compareAlgorithmVersions = (() => {
  interface CompareAlgorithmVersionsInput {
    version: string;
    dataset: Array<{
      meal_id: string;
      user_id: string;
      success: boolean;
      cooking_time_minutes: number;
      user_satisfaction_score: number;
    }>;
  }
  
  interface AlgorithmMetrics {
    success_rate_percentage: number;
    avg_cooking_time_minutes: number;
    user_satisfaction_score_0_to_100: number;
  }
  
  interface ImprovementRates {
    success_rate_improvement_percentage: number;
    cooking_time_reduction_percentage: number;
    satisfaction_score_improvement_percentage: number;
  }
  
  interface CompareAlgorithmVersionsResult {
    pre_improvement_version: string;
    post_improvement_version: string;
    pre_improvement_metrics: AlgorithmMetrics;
    post_improvement_metrics: AlgorithmMetrics;
    improvement_rates: ImprovementRates;
  }
  
  function calculateMetricsFromDataset(
    dataset: Array<{
      meal_id: string;
      user_id: string;
      success: boolean;
      cooking_time_minutes: number;
      user_satisfaction_score: number;
    }>
  ): AlgorithmMetrics {
    const successCount = dataset.filter((d) => d.success).length;
    const successRatePercentage = (successCount / dataset.length) * 100;
  
    const totalCookingTime = dataset.reduce(
      (sum, d) => sum + d.cooking_time_minutes,
      0
    );
    const avgCookingTime = totalCookingTime / dataset.length;
  
    const totalSatisfaction = dataset.reduce(
      (sum, d) => sum + d.user_satisfaction_score,
      0
    );
    const avgSatisfaction = totalSatisfaction / dataset.length;
  
    return {
      success_rate_percentage: successRatePercentage,
      avg_cooking_time_minutes: avgCookingTime,
      user_satisfaction_score_0_to_100: avgSatisfaction,
    };
  }
  
   function compareAlgorithmVersions(
    preVersion: CompareAlgorithmVersionsInput,
    postVersion: CompareAlgorithmVersionsInput
  ): CompareAlgorithmVersionsResult {
    const preMetrics = calculateMetricsFromDataset(preVersion.dataset);
    const postMetrics = calculateMetricsFromDataset(postVersion.dataset);
  
    const successRateDiff =
      postMetrics.success_rate_percentage - preMetrics.success_rate_percentage;
    const successRateImprovementPercentage =
      preMetrics.success_rate_percentage > 0
        ? (successRateDiff / preMetrics.success_rate_percentage) * 100
        : 0;
  
    const cookingTimeReduction =
      preMetrics.avg_cooking_time_minutes - postMetrics.avg_cooking_time_minutes;
    const cookingTimeReductionPercentage =
      preMetrics.avg_cooking_time_minutes > 0
        ? (cookingTimeReduction / preMetrics.avg_cooking_time_minutes) * 100
        : 0;
  
    const satisfactionScoreDiff =
      postMetrics.user_satisfaction_score_0_to_100 -
      preMetrics.user_satisfaction_score_0_to_100;
    const satisfactionScoreImprovementPercentage =
      preMetrics.user_satisfaction_score_0_to_100 > 0
        ? (satisfactionScoreDiff / preMetrics.user_satisfaction_score_0_to_100) *
          100
        : 0;
  
    return {
      pre_improvement_version: preVersion.version,
      post_improvement_version: postVersion.version,
      pre_improvement_metrics: preMetrics,
      post_improvement_metrics: postMetrics,
      improvement_rates: {
        success_rate_improvement_percentage: Math.max(
          0,
          successRateImprovementPercentage
        ),
        cooking_time_reduction_percentage: Math.max(
          0,
          cookingTimeReductionPercentage
        ),
        satisfaction_score_improvement_percentage: Math.max(
          0,
          satisfactionScoreImprovementPercentage
        ),
      },
    };
  }
  return { compareAlgorithmVersions };
})();
