/* AIVIC_FUNCTION_BUNDLE_START owner=extractFailurePatterns exports=extractFailurePatterns */
const __aivicBundle_30_extractFailurePatterns = (() => {
  function extractFailurePatterns(
    failureRecords: Array<{ rejection_reason: string }>,
    frequency_threshold_percent: number
  ): {
    failure_patterns: Array<{
      rejection_reason: string;
      occurrence_count: number;
      frequency_percent: number;
    }>;
    total_records_analyzed: number;
    analysis_threshold_percent: number;
  } {
    // Validate threshold
    if (frequency_threshold_percent < 0 || frequency_threshold_percent > 100) {
      throw new Error('閾値は0から100の範囲で指定してください');
    }
  
    const total_records_analyzed = failureRecords.length;
  
    // Handle empty records
    if (total_records_analyzed === 0) {
      return {
        failure_patterns: [],
        total_records_analyzed: 0,
        analysis_threshold_percent: frequency_threshold_percent,
      };
    }
  
    // Count occurrences of each rejection reason
    const reasonCounts: Record<string, number> = {};
    for (const record of failureRecords) {
      const reason = record.rejection_reason;
      reasonCounts[reason] = (reasonCounts[reason] || 0) + 1;
    }
  
    // Calculate frequency percentages and filter by threshold
    const failure_patterns = Object.entries(reasonCounts)
      .map(([rejection_reason, occurrence_count]) => {
        const frequency_percent = (occurrence_count / total_records_analyzed) * 100;
        return {
          rejection_reason,
          occurrence_count,
          frequency_percent,
        };
      })
      .filter((pattern) => pattern.frequency_percent >= frequency_threshold_percent)
      .sort((a, b) => b.frequency_percent - a.frequency_percent);
  
    return {
      failure_patterns,
      total_records_analyzed,
      analysis_threshold_percent: frequency_threshold_percent,
    };
  }
  return { extractFailurePatterns };
})();
export const extractFailurePatterns = __aivicBundle_30_extractFailurePatterns.extractFailurePatterns;
