const __aivicBundle_31_identifyFailurePatterns = (() => {
  function identifyFailurePatterns(input: {
    failureReasons: Array<{
      reasonId: string;
      category: string;
      frequency: number;
      description: string;
    }>;
    frequencyThreshold: number;
  }): {
    failurePatterns: Array<{
      reasonId: string;
      category: string;
      frequency: number;
      description: string;
    }>;
    excludedReasons: Array<{
      reasonId: string;
      category: string;
      frequency: number;
      description: string;
      excludeReason: string;
    }>;
    analysisMetadata: {
      appliedThreshold: number;
      totalInputReasons: number;
      extractedPatterns: number;
      excludedCount: number;
      analysisTimestamp: string;
    };
  } {
    const { failureReasons, frequencyThreshold } = input;
  
    if (frequencyThreshold < 0 || frequencyThreshold > 100) {
      throw new Error("頻出度閾値は0～100の範囲で指定してください");
    }
  
    if (!failureReasons || failureReasons.length === 0) {
      throw new Error("分析対象の却下・修正理由データが存在しません");
    }
  
    const failurePatterns: Array<{
      reasonId: string;
      category: string;
      frequency: number;
      description: string;
    }> = [];
  
    const excludedReasons: Array<{
      reasonId: string;
      category: string;
      frequency: number;
      description: string;
      excludeReason: string;
    }> = [];
  
    for (const reason of failureReasons) {
      if (reason.frequency >= frequencyThreshold) {
        failurePatterns.push({
          reasonId: reason.reasonId,
          category: reason.category,
          frequency: reason.frequency,
          description: reason.description,
        });
      } else {
        excludedReasons.push({
          reasonId: reason.reasonId,
          category: reason.category,
          frequency: reason.frequency,
          description: reason.description,
          excludeReason: "frequency_below_threshold",
        });
      }
    }
  
    failurePatterns.sort((a, b) => b.frequency - a.frequency);
  
    const analysisMetadata = {
      appliedThreshold: frequencyThreshold,
      totalInputReasons: failureReasons.length,
      extractedPatterns: failurePatterns.length,
      excludedCount: excludedReasons.length,
      analysisTimestamp: new Date().toISOString(),
    };
  
    return {
      failurePatterns,
      excludedReasons,
      analysisMetadata,
    };
  }
  return { identifyFailurePatterns };
})();
