      const differentiationAxisCandidates: any[] = [];
      const excludedFactors: any[] = [];
  
      for (const painFactor of input.painFactors) {
        const gapScore = painFactor.gapScore ?? 0;
        const isQualified = gapScore >= gapThreshold;
  
        if (isQualified) {
          const priorityScore =
            (painFactor.frequency ?? 0) * 0.4 +
            (painFactor.impact ?? 0) * 0.6 +
            (gapScore / 100) * 10;
  
          differentiationAxisCandidates.push({
            painFactorId: painFactor.painFactorId,
            name: painFactor.name,
            frequency: painFactor.frequency,
            impact: painFactor.impact,
            competitorCoverageScore: painFactor.competitorCoverageScore,
            ownAppCoverageScore: painFactor.ownAppCoverageScore,
            gapScore: gapScore,
            priorityScore: priorityScore,
            isQualifiedForDifferentiation: true,
          });
        } else {
          excludedFactors.push({
            painFactorId: painFactor.painFactorId,
            name: painFactor.name,
            gapScore: gapScore,
            reason: `ギャップスコアが閾値${gapThreshold}未満`,
          });
        }
      }
  
      return {
        differentiationAxisCandidates: differentiationAxisCandidates,
        excludedFactors: excludedFactors,
        totalQualifiedCount: differentiationAxisCandidates.length,
        totalExcludedCount: excludedFactors.length,
        gapThresholdUsed: gapThreshold,
      };
