/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeDataReliability exports=analyzeDataReliability */
const __aivicBundle_54_analyzeDataReliability = (() => {
  interface AnalyzeDataReliabilityInput {
    interview_records_count: number;
    app_log_entries_count: number;
    behavioral_metric_points: number;
    minimum_sample_threshold: number;
    reliability_score_threshold: number;
  }
  
  interface AnalyzeDataReliabilityOutput {
    reliability_score: number;
    requires_supplementary_data: boolean;
    status: string;
    recommended_supplementary_data_types: string[];
  }
  
   function analyzeDataReliability(
    input: AnalyzeDataReliabilityInput
  ): AnalyzeDataReliabilityOutput {
    const {
      interview_records_count,
      app_log_entries_count,
      behavioral_metric_points,
      minimum_sample_threshold,
      reliability_score_threshold,
    } = input;
  
    // Calculate reliability score for each data source
    // interview_reliability: ratio of collected to minimum threshold, capped at 100
    const interview_reliability = Math.min(
      (interview_records_count / minimum_sample_threshold) * 100,
      100
    );
  
    // log_reliability: normalized by a baseline (100), capped at 100
    const log_reliability = Math.min(
      (app_log_entries_count / 100) * 100,
      100
    );
  
    // metric_reliability: ratio of collected to minimum threshold, capped at 100
    const metric_reliability = Math.min(
      (behavioral_metric_points / minimum_sample_threshold) * 100,
      100
    );
  
    // Calculate overall reliability score as average of three sources
    const overall_reliability_score =
      (interview_reliability + log_reliability + metric_reliability) / 3;
  
    // Determine if supplementary data is required
    const requires_supplementary =
      overall_reliability_score < reliability_score_threshold;
  
    // Determine status based on reliability score
    const status =
      overall_reliability_score >= reliability_score_threshold
        ? "sufficient"
        : "insufficient";
  
    // Recommend supplementary data types if needed
    const recommended_types: string[] = [];
    if (requires_supplementary) {
      if (interview_reliability < 80) {
        recommended_types.push("interview_records");
      }
      if (log_reliability < 80) {
        recommended_types.push("app_usage_logs");
      }
      if (metric_reliability < 80) {
        recommended_types.push("behavioral_metrics");
      }
    }
  
    return {
      reliability_score: Math.round(overall_reliability_score),
      requires_supplementary_data: requires_supplementary,
      status: status,
      recommended_supplementary_data_types: recommended_types,
    };
  }
  return { analyzeDataReliability };
})();
export const analyzeDataReliability = __aivicBundle_54_analyzeDataReliability.analyzeDataReliability;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeDataReliability */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAnalysisTrustScore exports=calculateAnalysisTrustScore */
const __aivicBundle_55_calculateAnalysisTrustScore = (() => {
  interface SupplementationMethod {
    data_type: string;
    priority: number;
    method_name: string;
    description: string;
    execution_steps: string[];
    required_resources: string[];
    estimated_time_hours: number;
  }
  
  interface CalculateAnalysisTrustScoreInput {
    dataset: {
      interview_records_count: number;
      app_logs_count: number;
      user_attributes_collected: boolean;
      behavioral_logs_collected: boolean;
      purchase_history_collected: boolean;
      pain_factors: Array<{
        factor_type: string;
        frequency: number;
        impact_score: number;
      }>;
      total_required_data_points: number;
      actual_collected_data_points: number;
    };
    threshold: number;
  }
  
  interface CalculateAnalysisTrustScoreOutput {
    trust_score: number;
    requires_supplementation: boolean;
    missing_data_types: string[];
    supplementation_methods: SupplementationMethod[];
    expected_trust_score_after_supplementation: number;
    recommended_action: string;
  }
  
   function calculateAnalysisTrustScore(
    input: CalculateAnalysisTrustScoreInput
  ): CalculateAnalysisTrustScoreOutput {
    const { dataset, threshold } = input;
  
    // Calculate trust score based on data collection ratio
    const trustScore = Math.round(
      (dataset.actual_collected_data_points / dataset.total_required_data_points) *
        100
    );
  
    // Identify missing data types
    const missingDataTypes: string[] = [];
    if (!dataset.user_attributes_collected) {
      missingDataTypes.push("user_attributes");
    }
    if (!dataset.behavioral_logs_collected) {
      missingDataTypes.push("behavioral_logs");
    }
    if (!dataset.purchase_history_collected) {
      missingDataTypes.push("purchase_history");
    }
  
    // Determine if supplementation is required
    const requiresSupplementation = trustScore <= threshold;
  
    // Generate supplementation methods for missing data types
    const supplementationMethods: SupplementationMethod[] = [];
  
    if (requiresSupplementation) {
      const methodsMap: Record<string, SupplementationMethod> = {
        user_attributes: {
          data_type: "user_attributes",
          priority: 1,
          method_name: "questionnaire_survey",
          description:
            "ユーザーの属性情報を収集するための調査票を設計・配布し、回答結果を集計します",
          execution_steps: [
            "調査票の設計",
            "対象ユーザーへの配布",
            "回答結果の集計",
            "データの標準化",
          ],
          required_resources: ["調査ツール", "分析担当者"],
          estimated_time_hours: 24,
        },
        behavioral_logs: {
          data_type: "behavioral_logs",
          priority: 2,
          method_name: "app_instrumentation",
          description:
            "アプリケーションにトラッキング機能を追加し、ユーザーの行動ログを自動収集します",
          execution_steps: [
            "トラッキングコードの実装",
            "ログ収集インフラの構築",
            "データ検証",
            "ダッシュボード構築",
          ],
          required_resources: ["エンジニア", "分析ツール"],
          estimated_time_hours: 40,
        },
        purchase_history: {
          data_type: "purchase_history",
          priority: 3,
          method_name: "transaction_data_integration",
          description:
            "決済システムと連携し、ユーザーの購買履歴データを統合します",
          execution_steps: [
            "決済システムのAPI確認",
            "データ連携の実装",
            "データマッピング",
            "品質検証",
          ],
          required_resources: ["エンジニア", "決済システム管理者"],
          estimated_time_hours: 32,
        },
      };
  
      for (const missingType of missingDataTypes) {
        if (methodsMap[missingType]) {
          supplementationMethods.push(methodsMap[missingType]);
        }
      }
    }
  
    // Calculate expected trust score after supplementation
    let expectedTrustScoreAfterSupplementation = trustScore;
    if (requiresSupplementation) {
      // Estimate improvement based on missing data types count
      const improvementPerMissingType = 20;
      expectedTrustScoreAfterSupplementation = Math.min(
        100,
        trustScore + missingDataTypes.length * improvementPerMissingType
      );
    }
  
    // Determine recommended action
    let recommendedAction: string;
    if (requiresSupplementation) {
      recommendedAction =
        "補完方法に従いデータを収集し、再度分析を実行してください";
    } else {
      recommendedAction =
        "分析結果は信頼性が高く、差別化軸判定に進むことを推奨します";
    }
  
    return {
      trust_score: trustScore,
      requires_supplementation: requiresSupplementation,
      missing_data_types: missingDataTypes,
      supplementation_methods: supplementationMethods,
      expected_trust_score_after_supplementation:
        expectedTrustScoreAfterSupplementation,
      recommended_action: recommendedAction,
    };
  }
  return { calculateAnalysisTrustScore };
})();
export const calculateAnalysisTrustScore = __aivicBundle_55_calculateAnalysisTrustScore.calculateAnalysisTrustScore;
