/* AIVIC_FUNCTION_BUNDLE_START owner=generatePainPointDifferentiationList exports=generatePainPointDifferentiationList */
const __aivicBundle_63_generatePainPointDifferentiationList = (() => {
  function generatePainPointDifferentiationList(input: any): any {
    const {
      segment_type,
      pain_factors,
      differentiation_features,
      exclude_common_factors,
      min_specific_pain_factors,
    } = input;
  
    // Validate inputs
    const validPainFactors = Array.isArray(pain_factors) ? pain_factors : [];
    const validDifferentiationFeatures = Array.isArray(differentiation_features)
      ? differentiation_features
      : [];
  
    // Filter pain factors based on exclude_common_factors
    let filteredPainFactors = validPainFactors;
  
    if (exclude_common_factors) {
      filteredPainFactors = validPainFactors.filter(
        (pf: any) => pf.segment_type !== 'common'
      );
    }
  
    // Further filter to include only the target segment's specific factors
    const segmentSpecificFactors = filteredPainFactors.filter((pf: any) => {
      if (segment_type === 'househusband') {
        return pf.segment_type === 'househusband_specific';
      }
      return false;
    });
  
    // Count excluded common factors
    const commonFactorsExcludedCount = exclude_common_factors
      ? validPainFactors.filter((pf: any) => pf.segment_type === 'common').length
      : 0;
  
    // Map pain factors to differentiation features
    const differentiationFeaturesMapped = validDifferentiationFeatures.filter(
      (df: any) => {
        return segmentSpecificFactors.some(
          (pf: any) => pf.factor_id === df.target_pain_factor_id
        );
      }
    );
  
    // Build priority matrix - filter factors with impact_score >= 85
    const highPriorityFactors = segmentSpecificFactors.filter(
      (pf: any) => pf.impact_score >= 85
    );
  
    const priorityMatrix = {
      high_priority_factors: highPriorityFactors.map((pf: any) => ({
        factor_id: pf.factor_id,
        factor_name: pf.factor_name,
        impact_score: pf.impact_score,
      })),
    };
  
    // Determine excluded segments based on segment_type and exclude_common_factors
    const excludedSegments: string[] = [];
    if (segment_type === 'househusband') {
      excludedSegments.push('working_parent_specific');
      excludedSegments.push('homemaker_specific');
      if (exclude_common_factors) {
        excludedSegments.push('common');
      }
    }
  
    // Validate that we have at least min_specific_pain_factors included
    // This affects the business decision of whether to proceed with this segment
    const meetsMinimumThreshold =
      segmentSpecificFactors.length >= min_specific_pain_factors;
  
    // Build result
    const result = {
      segment_type,
      pain_factors: segmentSpecificFactors,
      differentiation_features: differentiationFeaturesMapped,
      common_factors_excluded_count: commonFactorsExcludedCount,
      househusband_specific_factors_included_count: segmentSpecificFactors.length,
      priority_matrix: priorityMatrix,
      generated_at: new Date().toISOString(),
      metadata: {
        excluded_segments: excludedSegments,
        meets_minimum_threshold: meetsMinimumThreshold,
      },
    };
  
    return result;
  }
  return { generatePainPointDifferentiationList };
})();
