/* AIVIC_FUNCTION_BUNDLE_START owner=generatePainPointAndDifferentiationList exports=generatePainPointAndDifferentiationList */
const __aivicBundle_64_generatePainPointAndDifferentiationList = (() => {
  function generatePainPointAndDifferentiationList(input: any): any {
    // Validate input
    if (!input) {
      throw new Error('入力データが必要です');
    }
  
    const { interviewRecords = [], usageLogData = [] } = input;
  
    // Check if interview records exist
    if (!interviewRecords || interviewRecords.length === 0) {
      throw new Error('インタビュー記録が必要です');
    }
  
    // Detect outliers in usage log data
    const outlierDetected = detectOutliers(usageLogData);
  
    // Determine analysis status
    const analysisStatus =
      usageLogData && usageLogData.length > 0 ? 'success' : 'partial';
  
    // Extract and aggregate pain categories from interview records
    const painCategoryMap = new Map<
      string,
      {
        occurrenceFrequency: number;
        impactScores: number[];
        priorityScores: number[];
        segmentIds: Set<string>;
      }
    >();
  
    interviewRecords.forEach((record: any) => {
      const painCategories = record.painCategories || [];
      const priority = record.priority || 1;
      const impactScore = calculateImpactScore(priority);
  
      painCategories.forEach((category: string) => {
        if (!painCategoryMap.has(category)) {
          painCategoryMap.set(category, {
            occurrenceFrequency: 0,
            impactScores: [],
            priorityScores: [],
            segmentIds: new Set(),
          });
        }
  
        const entry = painCategoryMap.get(category)!;
        entry.occurrenceFrequency += 1;
        entry.impactScores.push(impactScore);
        entry.priorityScores.push(priority);
        if (record.segmentId) {
          entry.segmentIds.add(record.segmentId);
        }
      });
    });
  
    // Build pain point matrix
    const painPointMatrix = Array.from(painCategoryMap.entries()).map(
      ([category, data], index) => {
        const avgImpactScore =
          data.impactScores.length > 0
            ? Math.round(
                (data.impactScores.reduce((a, b) => a + b, 0) /
                  data.impactScores.length) *
                  10
              ) / 10
            : 0;
  
        return {
          painCategory: category,
          occurrenceFrequency: data.occurrenceFrequency,
          impactScore: avgImpactScore,
          priorityRank: String(index + 1),
          affectedSegments: Array.from(data.segmentIds),
        };
      }
    );
  
    // Sort by impact score descending
    painPointMatrix.sort((a, b) => b.impactScore - a.impactScore);
  
    // Generate differentiation features based on pain points
    const differentiationFeatureList = painPointMatrix.map((pain, index) => {
      const featureId = `feature-${Date.now()}-${index}`;
      const priorityScore = 100 - index * 10;
  
      return {
        featureId,
        featureName: generateFeatureName(pain.painCategory),
        targetPainCategory: pain.painCategory,
        priorityScore,
        targetSegmentId:
          pain.affectedSegments.length > 0 ? pain.affectedSegments[0] : undefined,
      };
    });
  
    // Build result object
    const result: any = {
      painPointMatrix,
      differentiationFeatureList,
      analysisStatus,
      dataQualityReport: {
        outlierDetected,
      },
    };
  
    return result;
  }
  
  function calculateImpactScore(priority: number): number {
    // Convert priority to impact score (1 = 75, 2 = 50, 3 = 25, etc.)
    return Math.max(0, 100 - priority * 25);
  }
  
  function detectOutliers(usageLogData: any[]): boolean {
    if (!usageLogData || usageLogData.length === 0) {
      return false;
    }
  
    // Check for extreme values in cooking time or budget
    const cookingTimes = usageLogData
      .map((log: any) => log.cookingTimeMinutes)
      .filter((time: any) => typeof time === 'number');
  
    const budgets = usageLogData
      .map((log: any) => log.budgetConstraintJpy)
      .filter((budget: any) => typeof budget === 'number');
  
    if (cookingTimes.length > 0) {
      const avgCookingTime =
        cookingTimes.reduce((a: number, b: number) => a + b, 0) /
        cookingTimes.length;
      const hasOutlier = cookingTimes.some(
        (time: number) => time > avgCookingTime * 2 || time < avgCookingTime * 0.1
      );
      if (hasOutlier) return true;
    }
  
    if (budgets.length > 0) {
      const avgBudget =
        budgets.reduce((a: number, b: number) => a + b, 0) / budgets.length;
      const hasOutlier = budgets.some(
        (budget: number) =>
          budget > avgBudget * 2 || budget < avgBudget * 0.1
      );
      if (hasOutlier) return true;
    }
  
    return false;
  }
  
  function generateFeatureName(painCategory: string): string {
    const featureMap: Record<string, string> = {
      調理時間: '調理時間短縮機能',
      食材制限: '食材制限対応機能',
      予算制約: '予算最適化機能',
      栄養バランス: '栄養バランス自動調整',
      献立作成: '献立作成自動化',
    };
  
    return featureMap[painCategory] || `${painCategory}対応機能`;
  }
  return { generatePainPointAndDifferentiationList };
})();
